INSERT INTO "records" VALUES('words','ui',0,'{"page_title": "The Garden Gallery · Cedwyn", "kicker": "Cedwyn Estate", "title": "The Garden Gallery", "lede": "A quiet garden at the edge of the estate. Every piece here was grown from a photograph, a plan or a map in the Wayback Vault, and more are still coming up. Stay as long as you like.", "breathe": "breathe in for four, out for six", "grown_from": "Grown from", "edition_label": "Edition", "catalogue_label": "Catalogue number", "medium_label": "Medium", "medium": "Generative digital painting", "source_label": "Source record", "one_of_one": "1 of 1", "limited": "Limited edition of {n}", "buy": "Buy this digital edition", "shop": "Visit the gift shop", "back": "Back to the garden", "includes": "Instant high-resolution download with a certificate of authenticity. A digital edition, not a blockchain token."}');
